CREATE TABLE settings (id INTEGER PRIMARY KEY CHECK(id=1), value TEXT NOT NULL);
CREATE TABLE jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', created INTEGER NOT NULL, updated INTEGER NOT NULL, result TEXT);
CREATE INDEX jobs_status ON jobs(kind,status,created);
CREATE TABLE events (id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, created INTEGER NOT NULL, notified INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0);
CREATE INDEX event_notify ON events(notified,created);
CREATE TABLE sessions (id TEXT PRIMARY KEY, stage TEXT NOT NULL DEFAULT 'pin', attempts INTEGER NOT NULL DEFAULT 0, expires INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE limits (id TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE edge (id INTEGER PRIMARY KEY CHECK(id=1), value TEXT NOT NULL, updated INTEGER NOT NULL);
